function validate([word]) {
  if (word.length < 1 || word.length > 26) return 'word has between 1 and 26 letters.';
  if (!/^[a-z]+$/.test(word)) return 'word uses only lowercase English letters.';
  if (new Set(word).size !== word.length) return 'All letters in word must be distinct.';
  return null;
}

