function minimumPushes(word) {
  // Try every way of splitting the letters among the 8 keys; a key with c letters costs 1 + 2 + ... + c.
  const memo = new Map();
  const best = (key, left) => {
    if (key === 8) return left === 0 ? 0 : Infinity;
    const id = key * 100 + left;
    if (memo.has(id)) return memo.get(id);
    let result = Infinity;
    for (let c = 0; c <= left; c++) result = Math.min(result, (c * (c + 1)) / 2 + best(key + 1, left - c));
    memo.set(id, result);
    return result;
  };
  return best(0, word.length);
}

